  const items = ids.map(wardrobeItem);
  if (items.some((i) => !i)) return "Eleg\xED prendas del cat\xE1logo disponible.";
  const slots = items.map((i) => i.slot);
  if (new Set(slots).size !== slots.length)
    return "Eleg\xED una sola prenda por categor\xEDa.";
  if (slots.includes("top") && slots.includes("outerwear"))
    return "Eleg\xED un buzo o una campera para evitar superposiciones.";
