function dueReminders(s, instant) {
  if (!s.profile) return [];
  const now = localNow(s.profile.timezone, instant), date2 = now.toPlainDate().toString(), minute = now.hour * 60 + now.minute, p = s.preferences;
  if (!p.weekends && [0, 6].includes(weekday(date2))) return [];
  if (isQuiet(minute, p.quiet_start, p.quiet_end) || isQuiet(minute, s.profile.sleep_start, s.profile.sleep_end))
    return [];
  if (s.blocks.some(
    (b) => b.kind !== "AVAILABLE" && (b.exception_date ? b.exception_date === date2 : b.day_of_week === weekday(date2)) && minute >= b.start_minute && minute < b.end_minute
  ))
    return [];
  const drafts = [];
  if (p.checkin_enabled && !s.checkins.some((c) => c.date === date2 && c.outcome !== "UNCONFIRMED") && minute >= p.checkin_minute && minute <= p.checkin_minute + 180)
    drafts.push({
      id: "checkin",
      date: date2,
      title: "Un minuto para tu d\xEDa",
      body: "Registr\xE1 lo que aprendiste y ajustemos el pr\xF3ximo paso.",
      route: "today"
    });
  const plan = s.plans.find((x) => x.status === "ACCEPTED");
  for (const slot of plan?.slots ?? [])
    if (slot.status === "PENDING" && slot.date === date2 && minute >= slot.start_minute - 10 && minute <= slot.start_minute + 5)
      drafts.push({
        id: "session:" + slot.id,
        date: date2,
        title: "Tu pr\xF3ximo bloque est\xE1 cerca",
        body: "Tu plan tiene una sesi\xF3n preparada. Pod\xE9s revisar el objetivo.",
        route: "today"
      });
  for (const item of s.items)
    if (item.status === "PENDING" && item.due_date === date2 && item.due_time) {
      const [h, m] = item.due_time.split(":").map(Number), due = h * 60 + m;
      if (minute >= due - 60 && minute <= due - 45)
        drafts.push({
          id: "item:" + item.id,
          date: date2,
          title: "Un recordatorio de tu agenda",
          body: "Se acerca el horario de una actividad. Revis\xE1 lo que preparaste.",
          route: "agenda"
        });
    }
  return drafts;
}

